html, body { margin: 0; height: 100%; }
body { background: var(--board); color: var(--ink); font-family: var(--font-ui); font-size: 14px; line-height: 1.45;
       -webkit-font-smoothing: antialiased; }
a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }
button { font: inherit; color: inherit; }
code, .mono { font-family: var(--font-mono); font-size: 12.5px; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation: none !important; transition: none !important; } }

/* --- header ------------------------------------------------------------ */
.top { display: flex; align-items: center; gap: 20px; padding: 0 24px; height: 56px; border-bottom: 1px solid var(--line);
       background: var(--paper); position: sticky; top: 0; z-index: 5; }
.wordmark { display: flex; align-items: center; gap: 10px; font-weight: 700; letter-spacing: .02em; font-size: 15px; color: var(--ink); }
.wordmark:hover { text-decoration: none; }
.wordmark svg { width: 22px; height: 22px; }
.top .title { display: flex; align-items: baseline; gap: 12px; min-width: 0; }
.top .title h1 { font-size: 17px; font-weight: 600; margin: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.top .meta { color: var(--ink-2); font-family: var(--font-mono); font-size: 12px; white-space: nowrap; }
.top .spacer { flex: 1; }
.top .delta { font-family: var(--font-mono); font-size: 12px; color: var(--ink-2); white-space: nowrap; }
.top .delta b { font-weight: 500; }
.top .delta .up { color: var(--fail); } .top .delta .down { color: var(--pass); }
.ghost { background: none; border: 1px solid var(--line); border-radius: var(--radius); padding: 6px 10px; cursor: pointer;
         color: var(--ink-2); font-size: 13px; }
.ghost:hover { border-color: var(--ink-3); color: var(--ink); }

/* --- stamp (the signature) -------------------------------------------- */
.stamp { display: inline-flex; align-items: baseline; gap: 8px; font-family: var(--font-mono); font-weight: 500;
         text-transform: uppercase; letter-spacing: .14em; font-size: 13px; line-height: 1; padding: 9px 12px 8px;
         border: 2px solid currentColor; outline: 1.5px solid currentColor; outline-offset: 2.5px; border-radius: 2px;
         transform: rotate(-2deg); background: var(--paper); }
.stamp small { font-size: 10.5px; letter-spacing: .1em; opacity: .85; }
.stamp.PASS { color: var(--pass); } .stamp.WARN { color: var(--warn); } .stamp.FAIL { color: var(--fail); }
.stamp.big { font-size: 22px; padding: 14px 20px 12px; letter-spacing: .18em; }
.stamp.press { animation: press .32s cubic-bezier(.2, .9, .3, 1.2) both; }
@keyframes press { from { transform: rotate(-2deg) scale(1.35); opacity: 0; } to { transform: rotate(-2deg) scale(1); opacity: 1; } }

/* --- layout ------------------------------------------------------------ */
main { padding: 20px 24px 32px; max-width: 1600px; margin: 0 auto; }
.two { display: grid; grid-template-columns: minmax(0, 1.55fr) minmax(380px, 1fr); gap: 20px; align-items: start; }
@media (max-width: 1100px) { .two { grid-template-columns: 1fr; } }
.card { background: var(--paper); border: 1px solid var(--line-2); border-radius: 6px; box-shadow: var(--shadow-card); }

/* --- state 1: start ---------------------------------------------------- */
.start { max-width: 860px; margin: 28px auto 0; }
.start .lede { margin: 0 0 22px; }
.start .lede h2 { font-size: 30px; font-weight: 600; letter-spacing: -.01em; margin: 0 0 6px; }
.start .lede p { margin: 0; color: var(--ink-2); font-size: 15px; max-width: 60ch; }
.dropzone { position: relative; aspect-ratio: 420 / 297; max-height: 330px; width: 100%; background: var(--paper);
            border: 1.5px dashed var(--ink-3); border-radius: 3px; box-shadow: var(--shadow-sheet); cursor: pointer;
            display: flex; align-items: center; justify-content: center; text-align: center; transition: border-color .15s, transform .15s; }
.dropzone:hover, .dropzone.over { border-color: var(--accent); }
.dropzone.over { transform: translateY(-2px); }
.dropzone.has-file { border-style: solid; border-color: var(--ink); }
.dropzone input { position: absolute; inset: 0; opacity: 0; cursor: pointer; }
.dropzone .prompt strong { display: block; font-size: 19px; font-weight: 600; }
.dropzone .prompt span { color: var(--ink-2); }
.dropzone .prompt .file { font-family: var(--font-mono); font-size: 13px; color: var(--ink); margin-top: 6px; }
.dropzone .prompt .file em { font-style: normal; color: var(--ink-2); }
.dropzone .tb { position: absolute; right: 10px; bottom: 10px; display: grid; grid-template-columns: auto auto; border: 1px solid var(--line);
                font-family: var(--font-mono); font-size: 9.5px; letter-spacing: .08em; color: var(--ink-3); text-transform: uppercase; }
.dropzone .tb span { padding: 4px 8px; border-right: 1px solid var(--line); }
.dropzone .tb span:last-child { border-right: 0; color: var(--ink-2); }
.dropzone .north { position: absolute; top: 10px; right: 14px; font-family: var(--font-mono); font-size: 10px; color: var(--ink-3); }
.samples { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin: 18px 0 0; }
.sample { text-align: left; background: var(--paper); border: 1px solid var(--line); border-radius: var(--radius); padding: 10px 12px; cursor: pointer;
          display: flex; flex-direction: column; gap: 2px; transition: border-color .15s, box-shadow .15s; }
.sample:hover { border-color: var(--ink); box-shadow: var(--shadow-card); }
.sample b { font-weight: 600; }
.sample span { color: var(--ink-2); font-size: 12.5px; }
.sample .try { font-size: 11px; letter-spacing: .08em; text-transform: uppercase; color: var(--ink-3); font-family: var(--font-mono); }
.field { margin-top: 18px; }
.field label { display: block; font-size: 12.5px; font-weight: 600; color: var(--ink-2); margin-bottom: 6px; }
textarea, input[type=text] { width: 100%; font: inherit; padding: 9px 11px; border: 1px solid var(--line); border-radius: var(--radius); background: var(--paper);
           color: var(--ink); resize: vertical; }
textarea:focus, input[type=text]:focus { border-color: var(--accent); outline: none; box-shadow: 0 0 0 3px var(--accent-soft); }
textarea.mono { font-family: var(--font-mono); font-size: 12.5px; line-height: 1.5; white-space: pre; tab-size: 2; }
.actions { display: flex; align-items: center; gap: 12px; margin-top: 16px; }
.seg { display: inline-flex; border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; }
.seg button { background: var(--paper); border: 0; padding: 7px 12px; cursor: pointer; color: var(--ink-2); font-size: 13px; }
.seg button + button { border-left: 1px solid var(--line); }
.seg button.on { background: var(--ink); color: var(--paper); }
.btn { background: var(--ink); color: var(--paper); border: 1px solid var(--ink); padding: 9px 16px; border-radius: var(--radius); cursor: pointer;
       font-weight: 600; font-size: 14px; transition: background .15s; }
.btn:hover { background: #2A3139; }
.btn:disabled { opacity: .5; cursor: default; }
.btn.secondary { background: var(--paper); color: var(--ink); }
.btn.secondary:hover { background: var(--paper-2); }
.btn.accent { background: var(--accent); border-color: var(--accent); }
.btn.accent:hover { background: #2354BE; }
.btn.approve { background: var(--pass); border-color: var(--pass); }
.btn.approve:hover { background: #136A42; }
.err { color: var(--fail); background: var(--fail-soft); border: 1px solid #F0C4BF; border-radius: var(--radius); padding: 8px 12px; margin-top: 12px; }
.note { color: var(--ink-2); background: var(--paper-2); border: 1px solid var(--line-2); border-radius: var(--radius); padding: 8px 12px; margin-top: 12px; }
.recent { margin-top: 28px; border-top: 1px solid var(--line); padding-top: 14px; }
.recent h3 { font-size: 12px; text-transform: uppercase; letter-spacing: .08em; color: var(--ink-3); margin: 0 0 8px; }
.recent a { display: inline-flex; gap: 8px; align-items: center; margin: 0 14px 6px 0; color: var(--ink); font-size: 13px; }
.dot { width: 8px; height: 8px; border-radius: 50%; background: var(--ink-3); display: inline-block; }
.dot.PASS { background: var(--pass); } .dot.WARN { background: var(--warn); } .dot.FAIL { background: var(--fail); }

/* --- state 2: working -------------------------------------------------- */
.working { max-width: 720px; margin: 40px auto 0; padding: 26px 28px 22px; }
.working header { display: flex; align-items: baseline; justify-content: space-between; gap: 16px; margin-bottom: 18px; }
.working h2 { margin: 0; font-size: 20px; font-weight: 600; }
.working .clock { font-family: var(--font-mono); font-size: 22px; font-variant-numeric: tabular-nums; color: var(--ink-2); }
.steps { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }
.steps li { display: grid; grid-template-columns: 22px 150px 1fr; gap: 12px; align-items: center; padding: 8px 0; border-top: 1px solid var(--line-2); }
.steps li:first-child { border-top: 0; }
.steps .name { font-weight: 600; }
.steps .detail { color: var(--ink-2); font-family: var(--font-mono); font-size: 12px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.steps li.pending { color: var(--ink-3); } .steps li.pending .name { color: var(--ink-3); font-weight: 500; }
.steps li.failed .detail { color: var(--fail); white-space: normal; }
.glyph { width: 16px; height: 16px; border: 1.5px solid var(--ink-3); border-radius: 2px; display: inline-block; position: relative; }
.done .glyph { border-color: var(--ink); background: var(--ink); }
.done .glyph::after { content: ""; position: absolute; left: 4.5px; top: 1px; width: 4px; height: 8px; border: solid var(--paper); border-width: 0 2px 2px 0; transform: rotate(45deg); }
.running .glyph { border-color: var(--accent); animation: spin 1.1s linear infinite; }
.running .glyph::after { content: ""; position: absolute; inset: 3px; background: var(--accent); }
.failed .glyph { border-color: var(--fail); background: var(--fail); }
@keyframes spin { to { transform: rotate(360deg); } }
.devin-line { margin-top: 16px; padding-top: 14px; border-top: 1px solid var(--line-2); display: grid; grid-template-columns: 1fr auto; gap: 12px; align-items: start; }
.devin-line .msg { color: var(--ink); }
.devin-line .msg::before { content: "Devin · "; color: var(--ink-3); font-family: var(--font-mono); font-size: 12px; }
.devin-line .acu { font-family: var(--font-mono); font-size: 12px; color: var(--ink-2); white-space: nowrap; }
.working .foot { margin-top: 16px; display: flex; gap: 14px; align-items: center; color: var(--ink-2); font-size: 13px; }

/* --- state 3: result --------------------------------------------------- */
.viewer { position: relative; }
.viewer .bar { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; }
.viewer .bar .nav { display: inline-flex; border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; background: var(--paper); }
.viewer .bar .nav button { border: 0; background: none; width: 34px; height: 30px; cursor: pointer; color: var(--ink); font-size: 14px; }
.viewer .bar .nav button:hover { background: var(--paper-2); }
.viewer .bar .nav button:disabled { color: var(--line); cursor: default; }
.viewer .bar .sheetno { font-family: var(--font-mono); font-weight: 500; font-size: 13px; }
.viewer .bar .storey { font-weight: 600; }
.viewer .bar .count { color: var(--ink-3); font-family: var(--font-mono); font-size: 12px; }
.viewer .bar .spacer { flex: 1; }
.viewer .bar a { font-size: 13px; }
.sheet { display: block; position: relative; background: var(--paper); box-shadow: var(--shadow-sheet); border-radius: 2px; overflow: hidden;
         aspect-ratio: 2480 / 1754; }
.sheet img { display: block; width: 100%; height: 100%; object-fit: contain; }
.sheet .stamp { position: absolute; right: 26px; top: 22px; }
.sheet .stamp.approved { top: auto; bottom: 88px; right: 40px; color: var(--accent); }
.downloads { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 18px; margin-top: 12px; font-size: 13px; }
.downloads .lbl { color: var(--ink-3); font-family: var(--font-mono); font-size: 11px; letter-spacing: .08em; text-transform: uppercase; margin-right: 4px; }

.panel { display: flex; flex-direction: column; min-height: 420px; max-height: calc(100vh - 120px); }
.tabs { display: flex; border-bottom: 1px solid var(--line-2); padding: 0 6px; }
.tabs button { background: none; border: 0; border-bottom: 2px solid transparent; margin-bottom: -1px; padding: 12px 12px 10px; cursor: pointer;
               color: var(--ink-2); font-weight: 600; font-size: 13.5px; display: inline-flex; gap: 7px; align-items: center; }
.tabs button .n { font-family: var(--font-mono); font-weight: 400; font-size: 11.5px; color: var(--ink-3); }
.tabs button .n.bad { color: var(--fail); font-weight: 500; }
.tabs button.on { color: var(--ink); border-bottom-color: var(--ink); }
.tabs button:hover { color: var(--ink); }
.tabbody { overflow: auto; flex: 1; }
table { width: 100%; border-collapse: collapse; font-size: 13px; }
th { text-align: left; font-weight: 600; color: var(--ink-2); font-size: 11.5px; letter-spacing: .04em; text-transform: uppercase; padding: 8px 10px;
     border-bottom: 1px solid var(--line-2); position: sticky; top: 0; background: var(--paper); }
td { padding: 7px 10px; border-bottom: 1px solid var(--line-2); vertical-align: top; }
td.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }
tr.bad td { background: var(--fail-soft); }
tr.bad td:first-child { box-shadow: inset 3px 0 0 var(--fail); }
.tag { font-family: var(--font-mono); font-size: 12px; font-weight: 500; white-space: nowrap; }
.tag.bad { color: var(--fail); }
.muted { color: var(--ink-3); }
.rule { border-bottom: 1px solid var(--line-2); }
.rule .head { display: grid; grid-template-columns: auto 1fr auto; gap: 12px; align-items: baseline; padding: 11px 12px 8px; }
.rule .head .id { font-family: var(--font-mono); font-weight: 500; font-size: 12.5px; }
.rule .head .t { color: var(--ink-2); }
.rule .head .cnt { font-family: var(--font-mono); font-size: 12px; color: var(--ink-3); white-space: nowrap; }
.rule .head .cnt.bad { color: var(--fail); }
.sev { display: inline-block; font-family: var(--font-mono); font-size: 10.5px; letter-spacing: .08em; text-transform: uppercase; padding: 2px 6px; border-radius: 3px;
       margin-left: 6px; vertical-align: 1px; }
.sev.error { color: var(--fail); background: var(--fail-soft); } .sev.warning { color: var(--warn); background: var(--warn-soft); }
.finding { display: grid; grid-template-columns: 54px 92px 1fr auto; gap: 10px; padding: 6px 12px 6px; align-items: baseline; }
.finding.bad { background: var(--fail-soft); box-shadow: inset 3px 0 0 var(--fail); }
.finding .storey { color: var(--ink-2); font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.finding .vl { font-family: var(--font-mono); font-size: 12px; white-space: nowrap; color: var(--ink-2); }
.finding.bad .vl { color: var(--fail); }
.finding.ok { color: var(--ink-2); }
.rule details summary { cursor: pointer; color: var(--ink-3); font-size: 12px; padding: 4px 12px 8px; font-family: var(--font-mono); list-style: none; }
.rule details summary::before { content: "▸ "; } .rule details[open] summary::before { content: "▾ "; }
.clear { padding: 28px 16px; text-align: center; color: var(--ink-2); }
.clear .stamp { margin-bottom: 14px; }

.footer { margin-top: 20px; display: grid; grid-template-columns: minmax(0, 1.55fr) minmax(380px, 1fr); gap: 20px; align-items: start; }
@media (max-width: 1100px) { .footer { grid-template-columns: 1fr; } }
.request { padding: 14px 16px 16px; }
.request label { display: block; font-weight: 600; font-size: 13px; margin-bottom: 6px; }
.request .row { display: flex; gap: 10px; align-items: flex-start; }
.request textarea { min-height: 64px; }
.request .hint { color: var(--ink-3); font-size: 12px; margin-top: 6px; }
.decide { padding: 14px 16px 16px; display: flex; flex-wrap: wrap; gap: 10px; align-items: center; }
.decide .status { flex-basis: 100%; color: var(--ink-2); font-size: 13px; }
.decide .status b { color: var(--pass); }
.rules { margin-top: 20px; }
.rules summary { cursor: pointer; padding: 12px 16px; font-weight: 600; list-style: none; display: flex; align-items: center; gap: 10px; }
.rules summary::before { content: "▸"; color: var(--ink-3); } .rules[open] summary::before { content: "▾"; }
.rules summary .path { font-family: var(--font-mono); font-weight: 400; color: var(--ink-3); font-size: 12px; }
.rules summary .edited { font-family: var(--font-mono); font-size: 11px; color: var(--warn); background: var(--warn-soft); padding: 2px 6px; border-radius: 3px; }
.rules .body { padding: 0 16px 16px; }
.rules textarea { min-height: 320px; }
.rules .row { display: flex; gap: 10px; align-items: center; margin-top: 10px; }
.rules .row .hint { color: var(--ink-3); font-size: 12px; margin-left: auto; }
.toast { position: fixed; left: 50%; bottom: 24px; transform: translateX(-50%); background: var(--ink); color: var(--paper); padding: 10px 16px; border-radius: 6px;
         font-size: 13px; box-shadow: var(--shadow-sheet); z-index: 10; }
.toast.bad { background: var(--fail); }
EOF
echo "css $(wc -l < ui/static/style.css) lines"

